from store import *
def f(x,d=2):return f'{x:.{d}f}'.replace('.',',')
def diff(d):
    v=d['metrics']['full'];a,b=v['ci95']
    return f"{f(100*v['delta'],3)} п. п. [95% ДИ {f(100*a,3)} … {f(100*b,3)}], {d['wins']}/{d['losses']} выигранных/проигранных пар, p={d['p']:.4g}".replace('p=0.','p=0,')
def main():
    ver=read(D/'verified.json');db=read(D/'db-receipt.json')
    lines=['# Чтение ближайших невидимых интервалов из адресуемой памяти','',
             'Адрес уже выбран прежним ранжировщиком R25. Вычитание видимых диапазонов выполняется в SQLite при подготовке интервального представления. Два индексных запроса выбирают по три ближайших пробела вокруг той же компоненты. У каждого возвращённого отрезка собственный адрес. Проверка заново читает из SQLite байты каждого выданного диапазона. [Протокол](PROTOCOL_RU.md) · [SQL и планы запросов](db-receipt.json) · [оператор](reader.py)']
    for name,label in [('ise','ISETrace'),('mdd','MultiDoc2Dial')]:
        r=read(D/f'{name}-results.json');assert ver[name]['results']==sha(D/f'{name}-results.json')
        pair=r['equal']['window'];pr=r['paired']['window-equal'];observed=ver[name]['actual_different_gap_window']
        lines+=['',f'## {label}','',f"На {r['n']} вопросах и {r['groups']} группах при одинаковом расходе {f(pair[0]['tokens'])} токенов SQL-оператор обеспечивает полную поддержку в **{pair[0]['hits']}**, структурное окно в **{pair[1]['hits']}** случаях. Контраст gap минус окно {diff(pr)}. Покрытие составляет {f(100*pair[0]['coverage'])}% и {f(100*pair[1]['coverage'])}% соответственно. Оба варианта передают по {f(pair[0]['requests'])} и {f(pair[1]['requests'])} адресных диапазона в среднем. Фактические последовательности различаются у {observed['equal']} запросов при равной цене и у {observed['online']} при одинаковом онлайн-пределе.",'',
                '| Онлайн-оператор, потолок 256 | Полная поддержка | Покрытие | Токены | Адресных диапазонов | Повторные символы |','| --- | ---: | ---: | ---: | ---: | ---: |']
        for a,method in [('both','Обычный двусторонний'),('window','Окно строк/предложений'),('gap','Ближайшие пробелы SQLite')]:
            m=r['online'][a]
            lines.append(f"| {method} | {m['hits']}/{r['n']} | {f(100*m['coverage'])}% | {f(m['tokens'])} | {f(m['requests'])} | {f(100*m['repeat_pooled'])}% |")
        p=r['equal']['both'];lines+=['',f"При равной цене с обычным двусторонним чтением ({f(p[0]['tokens'])} токена) полная поддержка составляет {p[0]['hits']} и {p[1]['hits']}. Контраст {diff(r['paired']['both-equal'])}. Выбранное поле содержало одну структурную единицу в {r['single_structural_unit']} запросах. Нужная компонента отсутствовала в {r['no_component']}. [Индивидуальные показатели]({name}-outcomes.json.gz) · [полная статистика]({name}-results.json)"]
    lines+=['',f"Подготовленная SQLite-база занимает {db['bytes']:,} байт и хранит {db['counts']['fields']} пар «контекст, поле», {db['counts']['known']} уже известных интервалов и {db['counts']['gap']} пробелов. Данные этой реализации материализуют пробелы для каждого запроса. Компактность в системе с большой совместной памятью и стоимость инкрементальных обновлений здесь не измерены. Единица обращений в таблице — непустой возвращаемый диапазон или оплаченный адрес обычного контроля, не число физических чтений страниц. [SQL-план и объём](db-receipt.json) · [независимое воспроизведение](verified.json)",'',
             'Попарная равная цена рассчитывается после получения двух длин. Онлайн-режим ограничивает оба решения одним потолком. Результаты характеризуют наличие координат исходного доказательства при неизменном выборе наблюдения. Это вторичное исследование ранее использованных тестов, и вывод о новом лучшем методе потребует независимого подтверждения и оценки использования памяти решателем.']
    lines+=['','На ISETrace переход от обычного чтения к SQL устраняет повторные символы и сокращает расход, хотя среднее число адресных диапазонов возрастает. При одинаковом лимите SQL покрывает больше ответов, чем окно строк, и тратит больше токенов. При равном фактическом расходе преимущество над ним исчезает. В переносе на MultiDoc2Dial предложение как структурная единица даёт четыре дополнительных полных ответа при сопоставимой длине, а обычное двустороннее чтение совпадает с SQL по полному покрытию во всех парах. Эти результаты указывают на эффективность устранения повторов как операции хранения и чтения, а улучшение качества зависит от контроля и режима учёта расходов.']
    (D/'REPORT_RU.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    files={p.name:sha(p) for p in sorted(D.iterdir()) if p.is_file() and p.name!='manifest.json'}
    save(D/'manifest.json',{'files':files,'count':len(files),'bytes':sum((D/n).stat().st_size for n in files)})
if __name__=='__main__':main()
